'use strict';

// MODULES //

var hasSearchSymbolSupport = require( '@stdlib/assert/has-search-symbol-support' );


// MAIN //

/**
* Has instance symbol.
*
* @name SearchSymbol
* @constant
* @type {(symbol|null)}
*
* @example
* var SearchSymbol = require( '@stdlib/symbol/search' );
*
* function searcher() {
*     var obj = {};
*     obj[ SearchSymbol ] = function search( str ) {
*         // Return the index of substring 'foo':
*         return str.indexOf( 'foo' );
*     };
*     return obj;
* }
*
* var obj = searcher();
* var str = 'foobar';
*
* var result = str.search( obj );
* // returns 0
*/
var SearchSymbol = ( hasSearchSymbolSupport() ) ? Symbol.search : null;


// EXPORTS //

module.exports = SearchSymbol;
